const fcGlossary = {
  "ОДЗ": {
    title: "ОДЗ — область допустимых значений",
    text: "Все значения переменной, при которых исходное выражение или уравнение имеет смысл.",
    example: "Например, в 1/(x−2) значение x=2 запрещено."
  },
  "НОЗ": {
    title: "НОЗ — наименьший общий знаменатель",
    text: "Самый простой общий знаменатель, к которому удобно привести несколько дробей.",
    example: "Для 1/(2x) и 1/(3x) НОЗ равен 6x."
  },
  "НОК": {
    title: "НОК — наименьшее общее кратное",
    text: "Наименьшее положительное число, которое делится на каждое из данных чисел.",
    example: "НОК(6, 8)=24."
  },
  "D(f)": {
    title: "D(f) — область определения функции",
    text: "Все значения аргумента x, которые разрешено подставлять в функцию.",
    example: "Для f(x)=1/x: D(f)=ℝ\\{0}."
  },
  "E(f)": {
    title: "E(f) — множество значений функции",
    text: "Все значения y, которые функция может принимать.",
    example: "Для y=x²: E(f)=[0;+∞)."
  },
  "ℝ": {
    title: "ℝ — действительные числа",
    text: "Все числа числовой прямой: рациональные и иррациональные.",
    example: "Например: −3, 1/2, √2 и π принадлежат ℝ."
  },
  "ℚ": {
    title: "ℚ — рациональные числа",
    text: "Числа, которые можно представить дробью m/n, где m — целое, n≠0.",
    example: "Например: 3, −1/4, 0,125."
  },
  "∅": {
    title: "∅ — пустое множество",
    text: "Обозначает отсутствие подходящих значений или решений.",
    example: "x²=−1 не имеет действительных решений: ответ ∅."
  },
  "D": {
    title: "D — дискриминант",
    text: "Для квадратного уравнения ax²+bx+c=0: D=b²−4ac. По знаку D определяют число действительных корней.",
    example: "D>0 — два корня, D=0 — один, D<0 — действительных корней нет."
  }
};

function fcEnsureGlossaryTooltip(){
  let tip=document.querySelector("#glossaryTooltip");
  if(!tip){
    tip=document.createElement("div");
    tip.id="glossaryTooltip";
    tip.setAttribute("role","tooltip");
    document.body.appendChild(tip);
  }
  return tip;
}
function fcGlossaryHtml(key){
  const g=fcGlossary[key];
  return `<b>${g.title}</b><span>${g.text}</span>${g.example?`<small>${g.example}</small>`:""}`;
}
function fcPositionGlossary(term){
  const tip=fcEnsureGlossaryTooltip(),r=term.getBoundingClientRect();
  if(window.innerWidth<=620){tip.style.left="12px";tip.style.top="auto";return}
  tip.style.visibility="hidden";
  const tw=tip.offsetWidth||330,th=tip.offsetHeight||100,gap=8;
  let left=r.left+r.width/2-tw/2;
  left=Math.max(12,Math.min(window.innerWidth-tw-12,left));
  let top=r.bottom+gap;if(top+th>window.innerHeight-12)top=Math.max(12,r.top-th-gap);
  tip.style.left=left+"px";tip.style.top=top+"px";tip.style.visibility="";
}
function fcShowGlossary(term){
  const key=term.dataset.glossary;if(!fcGlossary[key])return;
  document.querySelectorAll(".glossary-term.open").forEach(x=>{if(x!==term)x.classList.remove("open")});
  term.classList.add("open");
  const tip=fcEnsureGlossaryTooltip();tip.innerHTML=fcGlossaryHtml(key);tip.classList.add("show");fcPositionGlossary(term);
}
function fcHideGlossary(term){
  term?.classList.remove("open");
  const tip=document.querySelector("#glossaryTooltip");
  if(tip){
    tip.classList.remove("show");
    tip.style.display="";
    tip.style.visibility="";
  }
}
function fcWrapGlossary(root=document.querySelector("#content")){
  if(!root)return;
  const keys=["D(f)","E(f)","ОДЗ","НОЗ","НОК","ℝ","ℚ","∅"];
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{
    acceptNode(node){
      const p=node.parentElement;
      if(!p||!node.nodeValue.trim()||p.closest(".glossary-term,script,style,button,input,textarea,select,option,canvas"))return NodeFilter.FILTER_REJECT;
      return keys.some(k=>node.nodeValue.includes(k))?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;
    }
  });
  const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(node=>{
    const text=node.nodeValue;
    const pattern=new RegExp("(" + keys.map(k=>k.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")).join("|") + ")","g");
    const parts=text.split(pattern);if(parts.length<2)return;
    const frag=document.createDocumentFragment();
    parts.forEach(part=>{
      if(fcGlossary[part]){
        const b=document.createElement("button");b.type="button";b.className="glossary-term";b.dataset.glossary=part;
        b.setAttribute("aria-label",fcGlossary[part].title+". Нажмите для пояснения.");b.textContent=part;frag.appendChild(b);
      }else frag.appendChild(document.createTextNode(part));
    });
    node.parentNode.replaceChild(frag,node);
  });

  // D размечаем только там, где контекст явно про дискриминант.
  root.querySelectorAll(".formula-card,.callout,.example-card,.exercise,.explain-pane").forEach(box=>{
    const text=box.textContent||"";
    if(!/дискриминант|D\s*[=<>]/i.test(text))return;
    const w=document.createTreeWalker(box,NodeFilter.SHOW_TEXT,{
      acceptNode(node){
        const p=node.parentElement;if(!p||p.closest(".glossary-term,button,input,textarea"))return NodeFilter.FILTER_REJECT;
        return /(^|[\s:(])D(?=\s*[=<>]|[),.;:\s]|$)/.test(node.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;
      }
    });
    const ns=[];while(w.nextNode())ns.push(w.currentNode);
    ns.forEach(node=>{
      const value=node.nodeValue,re=/(^|[\s:(])D(?=\s*[=<>]|[),.;:\s]|$)/g;
      let last=0,m,frag=document.createDocumentFragment(),changed=false;
      while((m=re.exec(value))){
        changed=true;const dIndex=m.index+m[1].length;
        frag.appendChild(document.createTextNode(value.slice(last,dIndex)));
        const b=document.createElement("button");b.type="button";b.className="glossary-term";b.dataset.glossary="D";
        b.setAttribute("aria-label",fcGlossary.D.title+". Нажмите для пояснения.");b.textContent="D";frag.appendChild(b);last=dIndex+1;
      }
      if(changed){frag.appendChild(document.createTextNode(value.slice(last)));node.parentNode.replaceChild(frag,node)}
    });
  });
}
let fcGlossaryScheduled=false;
function fcScheduleGlossary(){
  if(fcGlossaryScheduled)return;fcGlossaryScheduled=true;
  requestAnimationFrame(()=>{fcGlossaryScheduled=false;fcWrapGlossary()});
}

document.addEventListener("click",e=>{
  const term=e.target.closest?.(".glossary-term");
  if(term){e.preventDefault();e.stopPropagation();term.classList.contains("open")?fcHideGlossary(term):fcShowGlossary(term);return}
  fcHideGlossary(document.querySelector(".glossary-term.open"));
},true);
document.addEventListener("mouseover",e=>{
  if(window.matchMedia("(hover:hover)").matches){const term=e.target.closest?.(".glossary-term");if(term)fcShowGlossary(term)}
},true);
document.addEventListener("mouseout",e=>{
  if(window.matchMedia("(hover:hover)").matches){const term=e.target.closest?.(".glossary-term");if(term&&!term.contains(e.relatedTarget))fcHideGlossary(term)}
},true);
document.addEventListener("focusin",e=>{const term=e.target.closest?.(".glossary-term");if(term)fcShowGlossary(term)},true);
document.addEventListener("focusout",e=>{const term=e.target.closest?.(".glossary-term");if(term)fcHideGlossary(term)},true);
window.addEventListener("scroll",()=>fcHideGlossary(document.querySelector(".glossary-term.open")),{passive:true});
window.addEventListener("resize",()=>{const t=document.querySelector(".glossary-term.open");if(t)fcPositionGlossary(t)},{passive:true});

const fcGlossaryObserver=new MutationObserver(()=>fcScheduleGlossary());
fcGlossaryObserver.observe(document.querySelector("#content"),{childList:true,subtree:true});
