/* ---------- Контрольные в трёх уровнях ---------- */
const v11DifficultyInfo={
  base:["Базовый","Типовые задания по главным правилам главы. Хорошо подходит сразу после изучения."],
  mixed:["Смешанный","Половина типовых заданий и половина задач повышенной самостоятельности."],
  confident:["Уверенный","Задания со звёздочкой из разных тем. Подсказки появляются только после проверки."]
};
function v11EvenTopics(ch,count=6){
  if(ch.topics.length<=count)return ch.topics;
  const out=[];
  for(let i=0;i<count;i++){
    const idx=Math.round(i*(ch.topics.length-1)/(count-1));
    if(!out.includes(ch.topics[idx]))out.push(ch.topics[idx]);
  }
  return out;
}
function v11ChallengeControl(chId){
  const ch=chapters.find(c=>c.id===Number(chId));
  return v11EvenTopics(ch,6).map(t=>{
    const d=lessonData[t.id],c=d.challenge;
    return {q:c.q,a:c.a,tag:t.id,solution:c.hint||"Вернись к алгоритму урока и проверь каждый шаг."};
  });
}
function v11ControlSet(chId,level){
  const base=v1FinalData(chId).control.map(x=>({...x}));
  if(level==="base")return base;
  const hard=v11ChallengeControl(chId);
  if(level==="confident")return hard;
  const out=[];
  const n=Math.max(base.length,hard.length);
  for(let i=0;i<n&&out.length<6;i++){
    if(i%2===0 && base[i%base.length])out.push(base[i%base.length]);
    else if(hard[i%hard.length])out.push(hard[i%hard.length]);
  }
  return out.slice(0,6);
}
function v11ControlBest(chId,level){
  return Number(state.v11ControlBest[`${chId}:${level}`]||0);
}
function v11RenderControlPanel(chId,level="base"){
  const set=v11ControlSet(chId,level),info=v11DifficultyInfo[level],best=v11ControlBest(chId,level);
  return `<div class="v11-difficulty">
    ${Object.entries(v11DifficultyInfo).map(([k,v])=>`<button class="${k===level?"active":""}" onclick="v11SwitchControl(${chId},'${k}')">${v[0]}</button>`).join("")}
  </div>
  <div class="v11-level-info"><b>${info[0]} уровень.</b> ${info[1]} ${best?`Лучший результат: <b>${best}/${set.length}</b>.`:""}</div>
  <div class="callout warn"><b>Режим контрольной:</b> решай самостоятельно. Разбор появится после проверки.</div>
  <div class="control-grid">${set.map((q,i)=>`<div class="test-question" id="v11cq-${i}">
    <span class="fc-topic-badge">${lessonData[q.tag]?.title||""}</span>
    <h4>${i+1}. ${q.q}</h4><input class="control-answer" id="v11ca-${i}" placeholder="Ответ" autocomplete="off">
  </div>`).join("")}</div>
  <button class="primary glow-btn" style="margin-top:16px" onclick="v11SubmitControl(${chId},'${level}')">Проверить контрольную</button>
  <div id="v11ControlResult"></div>`;
}
window.v11SwitchControl=(chId,level)=>{
  const body=document.querySelector("#finalBody");if(body)body.innerHTML=v11RenderControlPanel(chId,level);
  fcScheduleGlossary?.();
};
window.v11SubmitControl=(chId,level)=>{
  const set=v11ControlSet(chId,level),weak=[];let score=0;
  set.forEach((q,i)=>{
    const val=document.querySelector(`#v11ca-${i}`)?.value||"",box=document.querySelector(`#v11cq-${i}`),ok=v1Match(val,q.a);
    box?.classList.toggle("correct",ok);box?.classList.toggle("wrong",!ok);
    let e=box?.querySelector(".test-explain");
    if(box&&!e){e=document.createElement("div");e.className="test-explain";box.appendChild(e)}
    if(ok){score++;if(e)e.textContent="✅ Верно."}
    else{weak.push(q.tag);if(e)e.innerHTML=`Правильный ответ: <b>${q.a[0]}</b>. ${q.solution||""}`}
  });
  const key=`${chId}:${level}`;
  state.v11ControlBest[key]=Math.max(Number(state.v11ControlBest[key]||0),score);
  const best=v1Best(chId);best.control=Math.max(best.control||0,score);state.v1Best[String(chId)]=best;
  ch1TouchActivity();v11Save();v1Result("v11ControlResult",score,set.length,weak);
};

/* Сохраняем исходный итог v1.0.1 для диагностики и шпаргалки. */
const v11BaseChapterFinal=v1RenderChapterFinal;
v1RenderChapterFinal=function(chapterOrTab=1,tab="test"){
  let chId=Number(chapterOrTab);
  if(typeof chapterOrTab==="string"&&["test","control","cheat"].includes(chapterOrTab)){chId=1;tab=chapterOrTab}
  if(tab!=="control")return v11BaseChapterFinal(chId,tab);

  const ch=chapters.find(c=>c.id===chId),d=v1FinalData(chId),b=v1Best(chId);
  setActive("chapterfinal");pageTitle.textContent=`Итог главы ${v1Roman(chId)}`;
  content.innerHTML=`<section class="final-hero reveal">
    <span class="eyebrow">Глава ${v1Roman(chId)} · ${d.title}</span>
    <h2 style="font-size:38px;margin:6px 0">Контрольная по уровню</h2>
    <p class="lead">Можно начать с базового уровня, затем перейти к смешанному и «Уверенному».</p>
    <div class="final-score-grid"><div class="final-score"><span class="muted">Уроки</span><b>${v1ChapterDone(ch)}/${ch.topics.length}</b></div>
    <div class="final-score"><span class="muted">Диагностика</span><b>${b.test?b.test+"/"+d.test.length:"—"}</b></div>
    <div class="final-score"><span class="muted">Лучший контроль</span><b>${b.control?b.control+"/6":"—"}</b></div></div>
    <div class="final-tabs"><button onclick="v1RenderChapterFinal(${chId},'test')">🎯 Диагностика</button>
    <button class="active" onclick="v1RenderChapterFinal(${chId},'control')">📝 Контрольная</button>
    <button onclick="v1RenderChapterFinal(${chId},'cheat')">📌 Шпаргалка</button>
    <button onclick="v1FinalHub()">← Все итоги</button></div>
    <div id="finalBody">${v11RenderControlPanel(chId,"base")}</div>
  </section>`;
  applyReveal();fcScheduleGlossary?.();
};
window.v1RenderChapterFinal=v1RenderChapterFinal;window.renderChapterFinal=v1RenderChapterFinal;

/* ---------- Визуальные мини-проверки после интерактивных лабораторий ---------- */
const v11VisualChecks={
  "1-8":{q:"Если k<0 в y=k/x, где находятся ветви?",opts:["I и III","II и IV","только справа"],ans:1,why:"При k<0 числа x и y имеют разные знаки, поэтому ветви лежат во II и IV четвертях."},
  "2-14":{q:"Когда x движется вправо по графику y=√x, что происходит с y?",opts:["возрастает","убывает","становится отрицательным"],ans:0,why:"Функция y=√x возрастает на всей области x≥0."},
  "3-21":{q:"Если D<0, что это означает для квадратного уравнения?",opts:["два корня","один корень","действительных корней нет"],ans:2,why:"При отрицательном дискриминанте √D не является действительным числом."},
  "4-39":{q:"В условии x>2 входит ли число 2 в решение?",opts:["да","нет"],ans:1,why:"Знак > строгий: граничная точка 2 не входит в промежуток."},
  "5-44":{q:"Если k<0 в y=kx+b, прямая слева направо…",opts:["поднимается","опускается","становится вертикальной"],ans:1,why:"Отрицательный угловой коэффициент означает убывание линейной функции."},
  "6-49":{q:"Какой коэффициент допустим в стандартном виде a·10ⁿ?",opts:["45","0,08","4,5"],ans:2,why:"В стандартном виде 1≤|a|<10."}
};
function v11VisualHtml(id,x){
  return `<div class="v11-visual-check reveal" data-v11-visual="${id}">
    <span class="eyebrow">👀 Проверь глазами</span><h4>${x.q}</h4>
    <div class="v11-visual-options">${x.opts.map((o,i)=>`<button onclick="v11VisualAnswer('${id}',${i},this)">${o}</button>`).join("")}</div>
    <div class="v11-visual-feedback" id="v11vf-${id}">Сначала посмотри на график или схему выше, затем выбери ответ.</div>
  </div>`;
}
window.v11VisualAnswer=(id,choice,btn)=>{
  const x=v11VisualChecks[id],box=btn.closest(".v11-visual-check"),out=document.querySelector(`#v11vf-${id}`);
  box.querySelectorAll(".v11-visual-options button").forEach(b=>b.classList.remove("correct","wrong"));
  if(choice===x.ans){btn.classList.add("correct");out.textContent="✅ "+x.why}
  else{btn.classList.add("wrong");out.textContent="🙂 Посмотри ещё раз на интерактив выше. "+x.why}
};
function v11InjectVisual(id){
  const x=v11VisualChecks[id];if(!x||document.querySelector(`[data-v11-visual="${id}"]`))return;
  const lab=document.querySelector(".graph-lab"),practice=document.querySelector("#practice");
  if(lab)lab.insertAdjacentHTML("afterend",v11VisualHtml(id,x));
  else if(practice)practice.insertAdjacentHTML("beforebegin",v11VisualHtml(id,x));
  applyReveal();fcScheduleGlossary?.();
}
const v11BaseOpenLesson=openLesson;
openLesson=function(id){v11BaseOpenLesson(id);setTimeout(()=>v11InjectVisual(id),40)};
window.openLesson=openLesson;

/* ---------- Более полезный экран прогресса ---------- */
function v11ReadinessHtml(){
  const ids=chapters.flatMap(c=>c.topics.map(t=>t.id));
  const mastery=Math.round(ids.reduce((s,id)=>s+v1Pct(id),0)/ids.length);
  const completed=state.completed.length;
  const acc=state.attempts?Math.round(state.correct/state.attempts*100):0;
  const weak=ids.map(id=>({id,p:v1Pct(id)})).filter(x=>x.p<50).sort((a,b)=>a.p-b.p).slice(0,6);
  const label=mastery>=85?"Отличная готовность 🌟":mastery>=65?"Хороший темп 👍":mastery>=40?"База формируется 💪":"Лучше двигаться небольшими шагами 🌱";
  return `<section class="v11-readiness reveal">
    <span class="eyebrow">Готовность по всему курсу</span><h2>${label}</h2>
    <p class="muted">Это не школьная оценка: показатель объединяет решённую практику, прохождение тем и текущую точность ответов.</p>
    <div class="v11-readiness-grid">
      <div class="v11-readiness-stat"><span class="muted">Освоение практики</span><b>${mastery}%</b></div>
      <div class="v11-readiness-stat"><span class="muted">Пройдено тем</span><b>${completed}/${TOTAL_TOPICS}</b></div>
      <div class="v11-readiness-stat"><span class="muted">Точность ответов</span><b>${state.attempts?acc+"%":"—"}</b></div>
    </div>
    ${weak.length?`<b>Что полезнее повторить сейчас</b><div class="v11-weak-list">${weak.map(x=>`<button class="secondary" onclick="openLesson('${x.id}')">${lessonData[x.id]?.title||x.id} · ${x.p}%</button>`).join("")}</div>`:`<div class="callout good">✅ Явных слабых тем по практике сейчас не видно.</div>`}
  </section>`;
}
const v11BaseProgress=renderProgress;
renderProgress=function(){
  v11BaseProgress();
  const first=content.firstElementChild;
  if(first)first.insertAdjacentHTML("beforebegin",v11ReadinessHtml());
  applyReveal();fcScheduleGlossary?.();
};
window.renderProgress=renderProgress;

